provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "example53.com"
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "www.example.com"
  type    = "CNAME"
  ttl     = 300
  records = ["192.0.2.101"]
  set_identifier = "NA Endpoint"
  geolocation_routing_policy {
    continent = "NA"
  }
}

resource "aws_route53_record" "eu_geolocation_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "service.example53.com"
  type    = "A"
  ttl     = "60"
  records = ["192.0.2.102"]
  set_identifier = "EU Endpoint"

  geolocation_routing_policy {
    continent = "EU" 
  }
}

responsePreview:
This Terraform configuration creates a public Route 53 hosted zone named `primary` and defines geolocation-based DNS routing records. Users located in the United States are routed to the US endpoint, while users located in Europe are routed to the EU endpoint. A default record is also included so that users outside the specified locations still receive a valid DNS response.

