      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region used by the provider. Route 53 is global, but AWS provider requires a region."
  type        = string
  default     = "us-east-1"
}

variable "zone_name" {
  description = "Name of the Route 53 hosted zone."
  type        = string
  default     = "primary"
}

